// Solo ejecutar en días de pago de quincena (14 o 30 / último día de mes)
const now = new Date();
const todayStr = now.toLocaleDateString('en-CA', { timeZone: 'America/Mexico_City' });
const [y, m, d] = todayStr.split('-').map(Number);
const daysInMonth = new Date(y, m, 0).getDate();

const isPayDay14 = (d === 14);
const isPayDay30 = (d === Math.min(30, daysInMonth));

if (!isPayDay14 && !isPayDay30) {
  return []; // No es día de inicio de quincena
}

const qLabel = isPayDay14 ? 'Q1' : 'Q2';
const quincenaTag = y + '-' + String(m).padStart(2, '0') + '-' + qLabel;

// Definir límites de la ventana quincenal
let fechaInicioVentana, fechaFinVentana;
const nextM = (m === 12) ? 1 : m + 1;
const nextY = (m === 12) ? y + 1 : y;

if (isPayDay14) {
  fechaInicioVentana = new Date(y, m - 1, 14, 0, 0, 0);
  fechaFinVentana = new Date(y, m - 1, 29, 23, 59, 59);
} else {
  const diaInicio = Math.min(30, daysInMonth);
  fechaInicioVentana = new Date(y, m - 1, diaInicio, 0, 0, 0);
  fechaFinVentana = new Date(nextY, nextM - 1, 13, 23, 59, 59);
}

const parametra = $('Leer Parametra').all().map(i => i.json).filter(j => j && j.parametro);
const vectigalia = $('Leer Vectigalia').all().map(i => i.json).filter(j => j && j.id && j.activo === 'SI');
const fides = $('Leer Fides (Tarjetas)').all().map(i => i.json).filter(j => j && j.tarjeta);
const acta = $('Leer Acta (Movimientos)').all().map(i => i.json).filter(j => j && j.tipo);

const chatId = parametra.find(p => p.parametro === 'telegram_chat_id')?.valor || '';
const ingresoEsperado = parseFloat(parametra.find(p => p.parametro === 'ingreso_quincenal_promedio')?.valor || 22200);
const pGasolina = parseFloat(parametra.find(p => p.parametro === 'presupuesto_gasolina_quincenal')?.valor || 1600);
const pPersonales = parseFloat(parametra.find(p => p.parametro === 'presupuesto_personales_quincenal')?.valor || 3000);
const presupuestoVariableTotal = pGasolina + pPersonales;
const umbralMargenMin = parseFloat(parametra.find(p => p.parametro === 'umbral_margen_minimo')?.valor || 1500);

// 1. Calcular compromisos fijos de Vectigalia respetando bimestralidad, fecha_inicio y fecha_fin
const compromisosVentana = [];
let totalFijosQuincena = 0;

for (const item of vectigalia) {
  if (item.tipo !== 'gasto') continue;
  const rawDias = String(item.dia || '').split(',').map(s => s.trim().toLowerCase());
  const monto = parseFloat(item.monto || 0);
  const frecuencia = (item.frecuencia || 'mensual').toLowerCase();

  for (const rawD of rawDias) {
    if (!rawD) continue;
    let diaTarget = (rawD === 'ultimo') ? daysInMonth : parseInt(rawD);
    if (isNaN(diaTarget)) continue;

    // Determinar fechas candidatas en el horizonte de la quincena
    const candidatos = [];
    if (isPayDay14) {
      if (diaTarget >= 14 && diaTarget <= 29) {
        candidatos.push({ anio: y, mes: m, dia: Math.min(diaTarget, daysInMonth) });
      }
    } else {
      // Q2: abarca días >= 30 del mes m y días <= 13 del mes nextM
      if (diaTarget >= 30) {
        candidatos.push({ anio: y, mes: m, dia: Math.min(diaTarget, daysInMonth) });
      } else if (diaTarget <= 13) {
        const daysInNextM = new Date(nextY, nextM, 0).getDate();
        candidatos.push({ anio: nextY, mes: nextM, dia: Math.min(diaTarget, daysInNextM) });
      }
    }

    for (const cand of candidatos) {
      const fechaCand = new Date(cand.anio, cand.mes - 1, cand.dia, 12, 0, 0);

      // Validar vigencia [fecha_inicio, fecha_fin]
      if (item.fecha_inicio) {
        const [iy, im, id] = item.fecha_inicio.split('-').map(Number);
        const inicioDate = new Date(iy, im - 1, id, 0, 0, 0);
        if (fechaCand < inicioDate) continue;
      }
      if (item.fecha_fin) {
        const [fy, fm, fd] = item.fecha_fin.split('-').map(Number);
        const finDate = new Date(fy, fm - 1, fd, 23, 59, 59);
        if (fechaCand > finDate) continue;
      }

      // Validar bimestralidad
      if (frecuencia === 'bimestral') {
        const mesInicio = parseInt(item.mes_inicio || 1);
        const anioInicio = item.fecha_inicio ? parseInt(item.fecha_inicio.split('-')[0]) : y;
        const deltaMeses = (cand.anio - anioInicio) * 12 + (cand.mes - mesInicio);
        if (deltaMeses < 0 || (deltaMeses % 2 !== 0)) continue;
      }

      if (fechaCand >= fechaInicioVentana && fechaCand <= fechaFinVentana) {
        compromisosVentana.push({
          concepto: item.concepto,
          dia: cand.dia,
          mes: cand.mes,
          monto: monto
        });
        totalFijosQuincena += monto;
      }
    }
  }
}

// 2. Incluir Tarjetas de Fides con pagada = NO y fecha_limite dentro de la ventana
const tarjetasVentana = [];
let totalTarjetasQuincena = 0;

for (const card of fides) {
  if (card.pagada === 'SI' || !card.fecha_limite) continue;
  const saldoCard = parseFloat(card.saldo_pago_sin_intereses || 0);
  if (saldoCard <= 0) continue;

  const [cy, cm, cd] = card.fecha_limite.split('-').map(Number);
  const flDate = new Date(cy, cm - 1, cd, 12, 0, 0);

  if (flDate >= fechaInicioVentana && flDate <= fechaFinVentana) {
    tarjetasVentana.push({
      tarjeta: card.tarjeta,
      monto: saldoCard,
      fecha_limite: card.fecha_limite
    });
    totalTarjetasQuincena += saldoCard;
  }
}

// Margen proyectado de maniobra (Ingreso - Fijos - Tarjetas sin intereses de la quincena - Variables)
const totalCompromisosQuincena = totalFijosQuincena + totalTarjetasQuincena;
const margenEstimado = ingresoEsperado - totalCompromisosQuincena - presupuestoVariableTotal;

let alertaMargen = '';
if (margenEstimado < umbralMargenMin) {
  alertaMargen = '⚠️ *ALERTA MARGEN BAJO:* Margen proyectado de $' + margenEstimado.toLocaleString('es-MX', {minimumFractionDigits: 2}) + ' está por debajo del umbral mínimo de $' + umbralMargenMin.toLocaleString('es-MX') + '. Revisa o modera tu gasto variable.';
} else {
  alertaMargen = '🟢 *Margen Saludable:* Tienes margen libre estimado de $' + margenEstimado.toLocaleString('es-MX', {minimumFractionDigits: 2}) + ' para contingencias o ahorro extra.';
}

const listaCompromisosStr = compromisosVentana.map(c => '  ▫️ ' + c.concepto + ' (' + c.dia + '-' + c.mes + '): $' + c.monto.toLocaleString('es-MX', {minimumFractionDigits: 2})).join('\n');
const listaTarjetasStr = tarjetasVentana.map(t => '  ▫️ ' + t.tarjeta + ' (límite ' + t.fecha_limite + '): $' + t.monto.toLocaleString('es-MX', {minimumFractionDigits: 2})).join('\n');

let mensaje = "🏛️ *Synaps Aerarium — Balance de Quincena (" + qLabel + ")*\n━━━━━━━━━━━━━━━━━━━━\n" +
  "📅 *Periodo:* `" + quincenaTag + "`\n" +
  "💵 *Ingreso Esperado:* $" + ingresoEsperado.toLocaleString('es-MX', {minimumFractionDigits: 2}) + "\n\n" +
  "📌 *Compromisos Fijos de la Quincena ($" + totalFijosQuincena.toLocaleString('es-MX', {minimumFractionDigits: 2}) + "):*\n" +
  (listaCompromisosStr || '  ▫️ Sin compromisos fijos en esta ventana') + "\n\n";

if (tarjetasVentana.length > 0) {
  mensaje += "💳 *Tarjetas de Crédito por Liquidar ($" + totalTarjetasQuincena.toLocaleString('es-MX', {minimumFractionDigits: 2}) + "):*\n" +
    listaTarjetasStr + "\n\n";
}

mensaje += "🛒 *Presupuestos Variables Apartados:* $" + presupuestoVariableTotal.toLocaleString('es-MX', {minimumFractionDigits: 2}) + "\n" +
  "  ▫️ Gasolina: $" + pGasolina.toLocaleString('es-MX') + "\n" +
  "  ▫️ Personales: $" + pPersonales.toLocaleString('es-MX') + "\n\n" +
  "━━━━━━━━━━━━━━━━━━━━\n" +
  "💰 *MARGEN ESTIMADO DE MANIOBRA:*\n👉 *$" + margenEstimado.toLocaleString('es-MX', {minimumFractionDigits: 2}) + " MXN*\n\n" +
  alertaMargen + "\n━━━━━━━━━━━━━━━━━━━━\n_Tabula Financia — Resumen Quincenal._";

return [{
  json: {
    chat_id: chatId,
    quincena: quincenaTag,
    ingreso: ingresoEsperado,
    fijos: totalFijosQuincena,
    tarjetas: totalTarjetasQuincena,
    variables: presupuestoVariableTotal,
    margen: margenEstimado,
    mensaje: mensaje
  }
}];
